import{_ as i,c as t,o as a,aj as r}from"./chunks/framework.CSCBGoZg.js";const m=JSON.parse('{"title":"Pipeline Steps","description":"","frontmatter":{},"headers":[],"relativePath":"reference/pipeline-step-overview.md","filePath":"reference/pipeline-step-overview.md","lastUpdated":0}'),n={name:"reference/pipeline-step-overview.md"};function o(s,e,p,c,l,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="pipeline-steps" tabindex="-1">Pipeline Steps <a class="header-anchor" href="#pipeline-steps" aria-label="Permalink to “Pipeline Steps”">​</a></h1><p>Pipeline steps are container images that perform dedicated actions.</p><p>You can use any container image that you like as a pipeline step, however, Reeve provides a collection of images to perform commonly used actions.</p><p>All pipeline steps run in <a href="https://docs.docker.com/reference/cli/docker/container/run/#interactive" target="_blank" rel="noreferrer">interactive mode</a>.</p><p>All pipeline steps share a common volume located at <code>/reeve</code>, other than that, they are isolated from each other. The common workdir to be used is at <code>/reeve/src</code>.</p><p>If specified in the pipeline definition, a host directory can be mounted at <code>/reeve/mount</code>. If this is the case, the working directory of the container is also set to this directory.</p><p>Pipeline steps can be configured using params, which are passed as environment variables to the container.</p><p>Additionally, the following environment variables are available for all containers:</p><ul><li><code>REEVE_PARAMS</code> contains a JSON encoded array of all params. This is used in some special cases when it is required to determine which environment variables where provided by Reeve and which come from the container OS.</li><li><code>REEVE_API</code> points to the container API that can be used to communicate with the pipeline runner (e.g. for setting runtime variables).</li></ul>',9)])])}const f=i(n,[["render",o]]);export{m as __pageData,f as default};
